The problem of the convergence of $\{\rho_{\varepsilon}\}_{\varepsilon >0}$, as $\varepsilon \searrow 0$ (i.\,e., as the kernel $\gamma_{\varepsilon}$ converges to a Dirac delta distribution\footnote{~We say that the family $\{\gamma_\varepsilon\}_{\varepsilon >0}$ converges to the Dirac delta $\delta_0$ (or is an \textit{approximation to the identity} (of the convolution product); see \cite[\S\,II.6.31]{MR1157815}) if 
$
\lim_{\varepsilon \to 0} \int_{\mathbb{R}} \varphi(z) \gamma_\varepsilon(z) \, \mathrm d z = \varphi(0)
$
for all test functions $\varphi \in \mathrm{C}(\mathbb R)$.
}) 
to the (unique\footnote{~We refer to \cite{MR1304494,MR3443431} for the well-posedness of entropy solutions of \cref{eq:cl}. 
}) entropy solution $\rho$ of the conservation law 
\begin{align}\label{eq:cl}
    \begin{cases}
        \partial_t \rho(t,x) + \partial_x\Big(V(\rho(t,x))\,\rho(t,x)\Big) = 0, & (t,x) \in \mathbb{R}_+ \times \mathbb{R}, \\
        \rho(0,x) = \rho_0(x), & x \in\mathbb{R},
    \end{cases}
\end{align}
has drawn much attention in the last few years.

\begin{align}\label{eq:Wevo-2}
\begin{cases}
\displaystyle  \partial_t W_{{\varepsilon}}(t,x)+V\left(W_{{\varepsilon}}(t,x)\right) \partial_x W_{{\varepsilon}}(t,x) & {} \\ 
\displaystyle \quad=\frac{1}{{\varepsilon}^2} \int_x^{\infty} \gamma^{\prime}\left(\frac{x-y}{{\varepsilon}}\right)\big( V\left(W_{{\varepsilon}}(t, x)\right)-V\left(W_{{\varepsilon}}(t, y)\right) \big) \rho_{{\varepsilon}}(t, y) \, \mathrm d y, & (t,x) \in \mathbb{R}_+ \times \mathbb{R}, \\ 
  \displaystyle  W_{{\varepsilon}}(0,x)=\frac{1}{{\varepsilon}}\int_{x}^{\infty}\gamma\left(\frac{x-y}{{\varepsilon}}\right)\rho_{0}(y)\,\mathrm{d} y, & x\in\mathbb{R}.
   \end{cases}
\end{align}

The TV-estimate $\mathrm{TV}(W_\varepsilon) \le \mathrm{TV}(\rho_0)$ and the convergence result for $W_{\varepsilon}$ were established earlier in \cite[Theorems 3.2 and 4.2]{MR4651679} in the particular case where $\gamma \coloneqq \mathds{1}_{]-\infty,0]}(\cdot)\exp(\cdot)$, leading to the identity  
\begin{align}\label{eq:WWxq}
    \partial_{x}W_{{\varepsilon}}[\rho_{{\varepsilon}}](t,x)&=\partial_{x}\, \left( \frac{1}{{\varepsilon}}\int_{x}^{\infty}\exp\left(\frac{x-y}{{\varepsilon}}\right)\rho_{{\varepsilon}}(t,y)\,\mathrm{d} y \right) =\frac{1}{{\varepsilon}}W_{{\varepsilon}}[\rho_{{\varepsilon}}](t,x)-\frac{1}{{\varepsilon}}\rho_{{\varepsilon}}(t,x).
\end{align}

In this work, we consider the following \textit{Godunov-type} numerical scheme\footnote{Following \cite{MR3917881}, we term the scheme a Godunov-type (or simply Godunov) scheme, interpreted as considering the Riemann problem for \cref{eq:cle} with $V=V(W_{{\varepsilon}}[\rho_{\varepsilon}])$ as a given velocity field; it can also be viewed as an upwinding scheme, as \cref{eq:cle} is linear in $\rho_{\varepsilon}$ with the given velocity field.} for \cref{eq:cle} and \cref{eq:W}:
\begin{align} \label{eq:godunov}
\rho_j^{n+1}&=\rho_j^n+\lambda (\rho_{j-1}^n V(W_j^n) -\rho_j^n V(W_{j+1}^n)), && j \in \mathbb Z, \ n\geq0,\\
 \label{eq:num_nonlocal_W}
    W_j^n &= \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k}^n, && j \in \mathbb Z, \ n\geq0,
\end{align}
where $\lambda\coloneqq \tau/h$ is the \textit{CFL} (\textit{Courant--Friedrichs--Levy}, \cite{MR1512478,MR213764}) \textit{ratio}, and $\{\gamma_k^{{\varepsilon},h}\}_{k\ge0}$ is a sequence of numerical quadrature weights such that 
$$
\gamma_{{\varepsilon},h} \coloneqq \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \, \mathds{1}_{]- \frac{(k+1){\varepsilon}}h, - \frac{k{\varepsilon}}h]}
$$
is a piecewise constant approximation of the nonlocal kernel $\gamma_{\varepsilon} =\tfrac{1}{\varepsilon} \gamma\left(\tfrac{\cdot}{{\varepsilon}}\right)$ on the spatial mesh grids with mesh size $h$.

\begin{align} \label{eq:godunov}
\rho_j^{n+1}&=\rho_j^n+\lambda (\rho_{j-1}^n V(W_j^n) -\rho_j^n V(W_{j+1}^n)), && j \in \mathbb Z, \ n\geq0,\\
 \label{eq:num_nonlocal_W}
    W_j^n &= \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k}^n, && j \in \mathbb Z, \ n\geq0,
\end{align}

\begin{align}\label{eq:W-2}
    W_j^{n+1} = W_j^n + \lambda \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \left( \rho_{j+k-1}^n V(W_{j+k}^n) - \rho_{j+k}^n V(W_{j+k+1}^n) \right), \qquad j \in \mathbb Z, \ n\geq0.
\end{align}

We assume that the family of quadrature weights  $\{\gamma_k^{{\varepsilon},h}\}_{k\ge0}$ satisfies the following conditions: 
\begin{align}\label{ass:pos-mono}
&\gamma_k^{{\varepsilon},h} \geq \gamma_{k+1}^{{\varepsilon},h}\geq 0, \qquad \text{for all } k\geq0;\\
&\sum_{k=0}^{\infty} \gamma_k^{{\varepsilon},h} = 1; \label{ass:normalize}\\ 
&\gamma_{k-1}^{{\varepsilon},h}+\gamma_{k+1}^{{\varepsilon},h}-2\gamma_k^{{\varepsilon},h}\geq 0, \qquad \text{for all } k\geq1; \label{ass:convexity} \\
\label{eq:quad_weight_localize}
&\lim_{R\to\infty}\sup_{{\varepsilon},h>0} \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}\ge R} \gamma^{{\varepsilon},h}_k = 0;
\\
&\sum_{k=0}^{\infty} k \gamma_k^{{\varepsilon},h} \leq c_\gamma \frac{{\varepsilon}}h, \qquad \text{with $c_\gamma>0$ depending only on $\gamma$.} \label{ass:gamma-mom}
\end{align}

\begin{align}\label{ass:pos-mono}
&\gamma_k^{{\varepsilon},h} \geq \gamma_{k+1}^{{\varepsilon},h}\geq 0, \qquad \text{for all } k\geq0;\\
&\sum_{k=0}^{\infty} \gamma_k^{{\varepsilon},h} = 1; \label{ass:normalize}\\ 
&\gamma_{k-1}^{{\varepsilon},h}+\gamma_{k+1}^{{\varepsilon},h}-2\gamma_k^{{\varepsilon},h}\geq 0, \qquad \text{for all } k\geq1; \label{ass:convexity} \\
\label{eq:quad_weight_localize}
&\lim_{R\to\infty}\sup_{{\varepsilon},h>0} \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}\ge R} \gamma^{{\varepsilon},h}_k = 0;
\\
&\sum_{k=0}^{\infty} k \gamma_k^{{\varepsilon},h} \leq c_\gamma \frac{{\varepsilon}}h, \qquad \text{with $c_\gamma>0$ depending only on $\gamma$.} \label{ass:gamma-mom}
\end{align}

 \label{th:main-2} 
Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{eq:quad_weight_localize}, and the CFL condition 
\begin{align}\label{ass:CFL}
   \lambda \Big(\norm{V}_{\mathrm{L}^\infty}+2\|V'\|_{\mathrm{L}^\infty}\Big) \leq 1
\end{align}
holds, with the CFL ratio $\lambda\coloneqq \tau/h$ fixed. Let us consider the numerical solutions $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}, and let $W_{{\varepsilon},h}$ be the piecewise constant reconstruction of $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$, i.\,e., 
\begin{align}\label{eq:W_piece_recon}
    W_{{\varepsilon},h} \coloneqq \sum_{n=0}^\infty \sum_{j\in\mathbb{Z}} W_j^n \,\cdot\, \mathds{1}_{[n\tau,(n+1)\tau[\times[(j-\frac12)h,(j+\frac12)h[}.
\end{align}
Then, as ${\varepsilon},h\searrow 0$, the approximate solution $W_{{\varepsilon},h}$ converges strongly in $\mathrm{L}^1_{\mathrm{loc}}$ to the unique entropy solution $\rho$ of \cref{eq:cl}. 
Moreover, assuming \cref{ass:gamma-mom}, the following error estimate holds: 
\begin{align}\label{eq:rate-thm}
\|W_{{\varepsilon},h}(t,\cdot)-\rho(t,\cdot)\|_{\mathrm{L}^1} \leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, t}+\sqrt{h\,t} \right)\, \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, t > 0,
\end{align}
where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$ (as specified in \cref{ass:gamma-mom}).

\[ K_n \ge 0, \qquad 
\|K_n\|_{\mathrm{L}^1} = 1, \qquad \int_{-\infty}^{-R} K_n(z) \, \mathrm d z + \int_{R}^{+\infty} K_n(z) \, \mathrm d z \to 0 \text{ as $n \to \infty$ for every fixed $R>0$.}
\]

\label{ex:exact}
The \emph{exact quadrature weights}
\begin{align}\label{eq:quad-2}
    \gamma_k^{{\varepsilon},h} = \int_{-(k+1)h}^{-kh} \frac1{\varepsilon} \gamma\left(\frac{z}{{\varepsilon}}\right) \,\mathrm{d} z = \int_{-(k+1)h/{\varepsilon}}^{-kh/{\varepsilon}} \gamma(z) \, \mathrm d z,
\end{align}
satisfy \crefrange{ass:pos-mono}{ass:gamma-mom}, with $c_\gamma\coloneqq \int_{\mathbb{R}} |z|\gamma(z)\, {\, \mathrm{d}z}$ being the first order moment of $\gamma$.

\label{ex:Riemann} 
The \emph{normalized Riemann quadrature weights}
\begin{align}\label{eq:quad-3}
\gamma_k^{{\varepsilon},h} = \frac1{\sum_{k=0}^\infty \tilde{\gamma}_k^{{\varepsilon},h}}\tilde{\gamma}_k^{{\varepsilon},h} \qquad \text{with } \qquad \tilde{\gamma}_k^{{\varepsilon},h} = \frac{h}{\varepsilon}\, \gamma\left(-\frac{kh}{\varepsilon}\right),
\end{align}
satisfy \crefrange{ass:pos-mono}{ass:gamma-mom} too, where $\gamma(0)$ is taken as $\gamma(0-)$ when $k=0$, and $c_\gamma\coloneqq 2\int_{\mathbb{R}} |z|\gamma(z)\, \mathrm d z$.

\label{rk:hfixed}
Let us fix $h>0$ and let $\varepsilon\searrow0$ in the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Under \cref{ass:normalize}, the limit of \cref{eq:num_nonlocal_W} gives $W_j^n=\rho_j^n$, thus \cref{eq:godunov} becomes
\begin{align}\label{eq:local_scheme}
    \rho_j^{n+1} = \rho_j^n + \lambda (\rho_{j-1}^n V(\rho_j^n) - \rho_j^n V(\rho_{j+1}^n)),
\end{align}
which together with \cref{eq:ini_cond_discrete} is a monotone scheme for the local conservation law \cref{eq:cl}.
Moreover, suppose that the kernel $\gamma$ is supported on a finite interval, without loss of generality, let us assume that $\operatorname{supp}\gamma\subset[-1,0]$. Then the scheme \crefrange{eq:godunov}{eq:ini_cond_discrete} reduces to \cref{eq:local_scheme} (with the initial condition \cref{eq:ini_cond_discrete}) when ${\varepsilon}\le h$.

\label{rk:epsfixed}
Assuming
    \begin{align}
    \frac{h}{\varepsilon}\gamma\left(-\frac{(k+1)h}\varepsilon\right)\le\gamma_k^{{\varepsilon},h}\le \frac{h}{\varepsilon}\gamma\left(-\frac{kh}\varepsilon\right) \label{ass:consist},
\end{align}
the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete} is consistent with the nonlocal conservation law \cref{eq:cle} for any fixed $\varepsilon >0$  (see \cite[Section 1]{MR4742183}, in particular the discussion surrounding Assumption 3, for details on the role of \cref{ass:consist}). 

We note that the assumption \cref{ass:consist}, together with \cref{ass:general-k}, implies \cref{ass:pos-mono} and \cref{eq:quad_weight_localize}; moreover, when combined with \cref{ass:momentum}, it implies \cref{ass:gamma-mom}.

\label{lem:maxm_prcp}
Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{ass:normalize}, and the CFL condition
\begin{align}\label{ass:CFL-max}
\lambda \Big(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\Big) \leq1
\end{align} holds. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following uniform bounds hold:
\begin{align*}
    \rho_{\mathrm{min}} \leq \rho_j^n \leq \rho_{\mathrm{max}} \qquad \textnormal{for all } j\in\mathbb{Z}, \ n\geq0,
\end{align*}
where $\rho_{\mathrm{min}}\coloneqq\inf_{x\in\mathbb{R}}\rho_0(x)\geq0$ and $\rho_{\mathrm{max}}\coloneqq\sup_{x\in\mathbb{R}}\rho_0(x)\leq1$.

We show $\rho_j^n \leq \rho_{\mathrm{max}}$ by induction. The base step for $n = 0$ follows from the definition of $\rho_{\mathrm{max}}$. Now, assuming that the result holds for $n$, we prove it for $n+1$. We have
\begin{align*}
\rho_j^{n+1} - \rho_{\mathrm{max}} &= (\rho_j^n - \rho_{\mathrm{max}}) \left(1 - \lambda V(W_{j+1}^n)\right) + \lambda \rho_{j-1}^n V(W_j^n) - \lambda \rho_{\mathrm{max}} V(W_{j+1}^n) \\
&\leq (\rho_j^n - \rho_{\mathrm{max}}) \left(1 - \lambda V(W_{j+1}^n)\right) + \lambda \rho_{\mathrm{max}}  \left( V(W_j^n) - V(W_{j+1}^n) \right).
\end{align*}
Using \cref{eq:num_nonlocal_W}, we deduce that 
\begin{align*}
    W_j^n - W_{j+1}^n &= \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} (\rho_{j+k}^n - \rho_{j+k+1}^n) 
    \\ &= \gamma_0^{{\varepsilon},h} \rho_j^n + \sum_{k=0}^\infty (\gamma_{k+1}^{{\varepsilon},h} - \gamma_k^{{\varepsilon},h}) \rho^n_{j+k+1} \\
    &\ge \gamma_0^{{\varepsilon},h} \rho_j^n + \rho_{\mathrm{max}} \sum_{k=0}^\infty (\gamma_{k+1}^{{\varepsilon},h}-\gamma_k^{{\varepsilon},h}) = \gamma_0^{{\varepsilon},h} (\rho_j^n - \rho_{\mathrm{max}}).
\end{align*}
We recall that $V' \leq 0$ and deduce that
\begin{align*}
    \rho_j^{n+1} - \rho_{\mathrm{max}} \leq (\rho_j^n - \rho_{\mathrm{max}}) \left(1 - \lambda V(W_{j+1}^n) - \lambda \rho_{\mathrm{max}}  \|V'\|_{\mathrm{L}^\infty} \gamma_0^{{\varepsilon},h} \right) \leq 0, 
\end{align*}
provided that $1 - \lambda V(W_{j+1}^n) - \lambda \rho_{\mathrm{max}}  \|V'\|_{\mathrm{L}^\infty} \gamma_0^{{\varepsilon},h} \geq 1 - \lambda \left(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\right)\geq0$ due to the CFL condition \cref{ass:CFL-max}.
The lower bound estimate $\rho_j^n \geq \rho_{\mathrm{min}}$ can be proved in a similar manner.

\begin{align*}
\rho_j^{n+1} - \rho_{\mathrm{max}} &= (\rho_j^n - \rho_{\mathrm{max}}) \left(1 - \lambda V(W_{j+1}^n)\right) + \lambda \rho_{j-1}^n V(W_j^n) - \lambda \rho_{\mathrm{max}} V(W_{j+1}^n) \\
&\leq (\rho_j^n - \rho_{\mathrm{max}}) \left(1 - \lambda V(W_{j+1}^n)\right) + \lambda \rho_{\mathrm{max}}  \left( V(W_j^n) - V(W_{j+1}^n) \right).
\end{align*}

\label{cor:L1_bound}
Under the conditions of \cref{lem:maxm_prcp}, we have
\begin{equation}
h\sum_{j\in\mathbb{Z}} |\rho_j^n| = h\sum_{j\in\mathbb{Z}} |\rho_j^0|\qquad \textnormal{for all } j\in\mathbb{Z}, \ n\geq0. \label{eq:L1_bound}
\end{equation}

Owing to \cref{lem:maxm_prcp}, we have $\rho_j^n \ge 0$ for all $j \in \mathbb Z$ and $n \ge 0$. We can then compute 
\begin{align*}
h \sum_j \rho_j^{n+1} = h \sum_j \left( \rho_j^n + \lambda \rho_{j-1}^n V(W_j^n) -\lambda \rho_j^n V(W_{j+1}^n)  \right) = h \sum_j \rho_j^n,
\end{align*}
which yields \cref{eq:L1_bound}.

\label{rk:W}
As a direct consequence of \crefrange{lem:maxm_prcp}{cor:L1_bound} and of the conditions \crefrange{ass:pos-mono}{ass:normalize} on quadrature weights, we deduce that $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ also satisfies
\begin{align}
    \rho_{\min} \le W_j^n \le \rho_{\max} \quad \textnormal{and}\quad h\sum_{j\in\mathbb{Z}} |W_j^n| = h\sum_{j\in\mathbb{Z}} |\rho_j^0| \qquad \textnormal{for all}\ j\in\mathbb{Z}, \ n\geq0,
\end{align}
with $\rho_{\mathrm{min}}\coloneqq\inf_{x\in\mathbb{R}}\rho_0(x)\geq0$ and $\rho_{\mathrm{max}}\coloneqq\sup_{x\in\mathbb{R}}\rho_0(x)\leq1$.

\begin{align}
    \rho_{\min} \le W_j^n \le \rho_{\max} \quad \textnormal{and}\quad h\sum_{j\in\mathbb{Z}} |W_j^n| = h\sum_{j\in\mathbb{Z}} |\rho_j^0| \qquad \textnormal{for all}\ j\in\mathbb{Z}, \ n\geq0,
\end{align}

\label{lm:TVD-x-2}
Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{ass:pos-mono}{ass:convexity}, and the CFL condition \cref{ass:CFL} holds. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following spatial $\mathrm{TV}$-estimate holds: 
\begin{align}\label{eq:TVD-x-2}
\sum_{j\in\mathbb{Z}} |W_{j+1}^{n+1}-W_j^{n+1}| \le \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n| \leq \mathrm{TV}(\rho_0), \qquad \textnormal{for all $n\ge0$.}
\end{align}

\label{lm:use_for_tv}
Under the conditions of \cref{lem:maxm_prcp}, we have
\begin{align}\label{eq:TV-p1}
    \sum_{j\in\mathbb{Z}}\rho_{j+k}^n |V(W_{j+k+1}^n) -V(W_j^n)| \leq \sum_{j\in\mathbb{Z}} \left(\sum_{l=0}^k \rho_{j+l}^n\right) |V(W_{j+1}^n) -V(W_j^n)|.
\end{align}

\label{lm:TVD-t-general}
Under the conditions of \cref{lm:TVD-x-2},  the following temporal $\mathrm{TV}$-estimate holds:  
\begin{align}\label{eq:TVD-t-general}
    \sum_{j\in\mathbb{Z}} |W_j^{n+1}-W_j^n| \leq \lambda \left(\|V\|_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^{\infty}}\right) \mathrm{TV}(\rho_0), \qquad \textnormal{for all $n\ge0$.}
\end{align}

It follows from \cref{eq:W-2} and \cref{eq:num_nonlocal_W} that
\begin{align*}
    W_j^{n+1} &= W_j^n + \lambda ( W_{j-1}^n - W_j^n ) V(W_j^n)  \\
    &\qquad + \lambda \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \Big( \rho_{j+k-1}^n \left( V(W_{j+k}^n) - V(W_j^n) \right) - \rho_{j+k}^n \left( V(W_{j+k+1}^n) - V(W_j^n) \right) \Big) \\
    &= W_j^n + \lambda ( W_{j-1}^n - W_j^n ) V(W_j^n) + \lambda \sum_{k=0}^\infty \left(\gamma_{k+1}^{{\varepsilon},h}-\gamma_k^{{\varepsilon},h}\right) \rho_{j+k}^n \left( V(W_{j+k+1}^n) - V(W_j^n) \right),
\end{align*}
where in the last step we have used the summation by parts.
Then we have
\begin{align*}
    \sum_{j\in\mathbb{Z}} |W_j^{n+1}-W_j^n| &\leq \lambda \norm{V}_{\mathrm{L}^\infty} \sum_{j\in\mathbb{Z}} |W_j^n-W_{j-1}^n| \\ & \qquad  + \lambda \sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \sum_{j\in\mathbb{Z}} \rho_{j+k}^n \left| V(W_{j+k+1}^n) - V(W_j^n) \right|.
\end{align*}
Next, we use \cref{eq:TV-p1} in \cref{lm:use_for_tv} to deduce
\begin{align*}
    &\sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \sum_{j\in\mathbb{Z}} \rho_{j+k}^n \left| V(W_{j+k+1}^n) - V(W_j^n) \right| \\
    &\leq \sum_{j\in\mathbb{Z}} \left( \sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \left(\sum_{l=0}^k \rho_{j+l}^n\right) \right) |V(W_{j+1}^n) -V(W_j^n)| \\
    &= \sum_{j\in\mathbb{Z}} \left( \gamma_0\rho_j^n + \sum_{k=0}^\infty \gamma_{k+1}^{{\varepsilon},h} \rho_{j+k+1}^n \right) |V(W_{j+1}^n) -V(W_j^n)| \\
    &= \sum_{j\in\mathbb{Z}} W_j^n |V(W_{j+1}^n) -V(W_j^n)| \\
    &\leq \|V'\|_{\mathrm{L}^\infty} \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n|.
\end{align*}
Then, using \cref{lm:TVD-x-2}, we conclude that \cref{eq:TVD-t-general} holds.

\begin{align*}
    W_j^{n+1} &= W_j^n + \lambda ( W_{j-1}^n - W_j^n ) V(W_j^n)  \\
    &\qquad + \lambda \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \Big( \rho_{j+k-1}^n \left( V(W_{j+k}^n) - V(W_j^n) \right) - \rho_{j+k}^n \left( V(W_{j+k+1}^n) - V(W_j^n) \right) \Big) \\
    &= W_j^n + \lambda ( W_{j-1}^n - W_j^n ) V(W_j^n) + \lambda \sum_{k=0}^\infty \left(\gamma_{k+1}^{{\varepsilon},h}-\gamma_k^{{\varepsilon},h}\right) \rho_{j+k}^n \left( V(W_{j+k+1}^n) - V(W_j^n) \right),
\end{align*}

\begin{align*}
    I_{2,{\varepsilon}} &= \partial_x \eta'(W_{\varepsilon}) \, ((V(W_{\varepsilon}) \rho_{\varepsilon}) \ast \gamma_{\varepsilon}) - \partial_x I_\eta(W_{\varepsilon}) \, W_{\varepsilon} \\
    &= \partial_x \eta'(W_{\varepsilon}) \, ((V(W_{\varepsilon}) \rho_{\varepsilon}) \ast \gamma_{\varepsilon}) - \partial_x I_\eta(W_{\varepsilon}) \, (\rho_{\varepsilon} \ast \gamma_{\varepsilon}) \\ &\eqqcolon I_{2a,{\varepsilon}} - I_{2b,{\varepsilon}}.
