\\ &= \partial_x \big( \big( \rho_{\varepsilon}(t,\cdot) H_\eta(W_{\varepsilon}(t,x)\mid W_{\varepsilon}(t,\cdot)) \big) \ast\gamma_{\varepsilon} \big) - \big( \rho_{\varepsilon}(t,\cdot)  H_\eta(W_{\varepsilon}(t,x)\mid W_{\varepsilon}(t,\cdot)) \big) \ast\gamma'_{\varepsilon}.
