\label{lm:discrete-entropy-2}
Under the conditions of \cref{lem:maxm_prcp}, the following discrete entropy inequality holds:
\begin{align}\label{eq:discrete-entropy-2}
    &\frac{|W_j^{n+1}-c| -|W_j^n-c|}{\tau} + \frac{\Psi_{j+1/2}^n - \Psi_{j-1/2}^n}{h} \leq 0, \qquad \mathrm{for\ all}\  c\in\mathbb{R}, \\
    \label{eq:entropy-flux-2} &\mathrm{with} \quad \Psi_{j-1/2}^n \coloneqq |W_{j-1}^n-c|V(c) - \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left|V(W_{j+k}^n)-V(c)\right|.
\end{align}

From \cref{lm:discrete-entropy-2}, multiplying \cref{eq:discrete-entropy-2} by $ \phi_j^n \tau h\coloneqq\phi(n\tau,jh)\tau h$, where $\phi\in \mathrm{C}_{\mathrm{c}}^1(\mathbb{R}_+\times\mathbb{R})$ is any test function, and summing it over all $j\in\mathbb{Z}$ and $n\geq0$, we obtain
\begin{align*}
    \tau h\sum_{n=0}^\infty\sum_{j\in\mathbb{Z}} |W_j^{n+1}-c| \frac{\phi_j^{n+1}-\phi_j^n}{\tau} + \Psi_{j-1/2}^n \frac{\phi_j^n-\phi_{j-1}^n}{h} \geq 0,
\end{align*}
for all $c\in\mathbb{R}$. By passing to the limit as $\tau=\lambda h\searrow 0,\,{\varepsilon}\searrow 0$, and using the fact that
\begin{align*}
    \Psi_{j-1/2}^n &= |W_{j-1}^n-c|V(c) - \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left|V(W_{j+k}^n)-V(c)\right| \\
    &= |W_{j-1}^n-c|V(c) - \left|V(W_j^n)-V(c)\right| W_{j-1}^n \\
    &\qquad + \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left( \left|V(W_j^n)-V(c)\right| - \left|V(W_{j+k}^n)-V(c)\right| \right),
\end{align*}
where the last term is controlled by $\|V'\|_{\mathrm{L}^\infty} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} |W_{j+k}^n - W_j^n|$,
we deduce that
\begin{align*}
    &\int_0^\infty\int_{\mathbb{R}} \big( |\rho^\ast-c|\partial_t\phi + \psi_c(\rho^\ast)\partial_x\phi \big) \,\mathrm{d} x\,\mathrm{d} t + \limsup_{\substack{{\varepsilon},h\searrow0}} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k \geq 0,
\end{align*}
where $\psi_c(\xi)\coloneqq\sgn{\xi-c}(\xi V(\xi)-cV(c))=|\xi-c|V(c)-|V(\xi)-V(c)|\xi$ is Kru\v{z}kov's entropy flux function, and
\begin{align*}
    H^{{\varepsilon},h}_k \coloneqq \tau h \sum_{n=0}^\infty\sum_{j\in\mathbb{Z}} |W_{j+k}^n - W_j^n| \left|\frac{\phi_j^n - \phi_{j-1}^n}{h}\right|.
\end{align*}
We keep in mind that all $W_j^n$ are ${\varepsilon},h$-dependent.

Suppose that $\mathrm{supp}(\phi)\subset[0,T]\times[-M,M]$. Following \cite[Lemma 4.1 and Theorem 1.2]{MR4553943}, we split the sum over \( k \) and write
\begin{align*}
\sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k
&= \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}< R}\gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k + \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}\ge R}\gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k,
\end{align*}
for any $R>0$.

On the one hand, noting that $H^{{\varepsilon},h}_k$ is uniformly bounded, i.\,e.,
$$
H^{{\varepsilon},h}_k \le 4 \|\partial_x \phi\|_{\mathrm{L}^\infty} MT \quad \text{for all}\ k\geq0,\,{\varepsilon},h>0,
$$
by \cref{eq:quad_weight_localize} we have
\begin{align*}
    \lim_{R\to\infty} \sup_{{\varepsilon},h>0}  \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}\ge R}\gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k  = 0.
\end{align*}
On the other hand, when $\frac{kh}{\varepsilon}< R$, we have
\begin{align*}
    H^{{\varepsilon},h}_k &\le \|\partial_x \phi\|_{\mathrm{L}^\infty} \int_0^T\int_{-M-kh}^M |W_{{\varepsilon},h}(t,x+kh)-W_{{\varepsilon},h}(t,x)| {\, \mathrm{d}x}{\, \mathrm{d}t} \\
    &\leq \|\partial_x \phi\|_{\mathrm{L}^\infty} \sup_{0\le\xi\le R{\varepsilon}} \int_0^T\int_{-M-R{\varepsilon}}^M |W_{{\varepsilon},h}(t,x+\xi)-W_{{\varepsilon},h}(t,x)| {\, \mathrm{d}x}{\, \mathrm{d}t} \\
    &\coloneqq J^{{\varepsilon},h}_R.
\end{align*}
By Fréchet--Kolmogorov--Riesz--Sudakov's theorem (see \cite{zbMATH05817642,zbMATH06579393,zbMATH07077498}), we deduce that $J^{{\varepsilon},h}_R\to0$ as ${\varepsilon},h\searrow0$. 

Now, for any $\nu>0$, we first choose $R$ sufficiently large such that
\begin{align*}
    \sup_{{\varepsilon},h>0} \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}\ge R}\gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k \leq \nu.
\end{align*}
Then, we estimate
\begin{align*}
    \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}< R}\gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k  \leq \|\partial_x \phi\|_{\mathrm{L}^\infty} \sum_{k=0}^\infty \mathds{1}_{\frac{kh}{\varepsilon}< R}\gamma_k^{{\varepsilon},h} J^{{\varepsilon},h}_R \le \|\partial_x \phi\|_{\mathrm{L}^\infty} J^{{\varepsilon},h}_R,
\end{align*}
which converges to zero as ${\varepsilon},h\searrow0$, implying that $\limsup_{{\varepsilon},h\searrow0} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k \le \nu$.
Since $\nu>0$ is arbitrarily chosen, we conclude that $\limsup_{{\varepsilon},h\searrow0} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} H^{{\varepsilon},h}_k=0$.
Therefore, we obtain
\begin{align*}
    \int_0^\infty\int_{\mathbb{R}} \big( |\rho^\ast-c|\partial_t\phi + \psi_c(\rho^\ast)\partial_x\phi \big) \,\mathrm{d} x\,\mathrm{d} t \geq 0,
\end{align*}
for all $\phi\in \mathrm{C}_{\mathrm{c}}^1(\mathbb{R}_+\times\mathbb{R})$ and $c\in\mathbb{R}$, thus $\rho^\ast$ is the unique entropy solution of \cref{eq:cl}.

\label{th:rate}
Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy  \crefrange{ass:pos-mono}{ass:convexity} and \cref{ass:gamma-mom}, and the CFL condition \cref{ass:CFL} holds with the CFL ratio $\lambda\coloneqq \tau/h$ fixed. Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Let $W_{{\varepsilon},h}$ be the approximate solution constructed from $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ using \cref{eq:W_piece_recon}, and $\rho$ be the unique entropy solution of \cref{eq:cl}.
Then the following error estimate holds:
\begin{align*}
\|W_{{\varepsilon},h}(T,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} \leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, T}+\sqrt{h\, T} \right) \mathrm{TV}(\rho_0), \quad \textnormal{for every } {\varepsilon},h > 0, \, T > 0,
\end{align*}
where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$ (as specified in \cref{ass:gamma-mom}).

 \label{lm:kut} 
Let 
\begin{align*} v \in \mathcal K \coloneqq \Big\{ v: \mathbb{R}_+\times \mathbb{R} \to \mathbb{R} \, : \ & v(t,\cdot) \in \mathrm{L}^1_{\mathrm{loc}}(\mathbb{R}) \textnormal{ and the right and left limits $v(t \pm, \cdot)$ exist in $\mathrm L^1_{\mathrm{loc}}$} \\ 
&\textnormal{for all $t>0$ \quad\ \, and \quad\ \,  } \|v\|_{\mathrm{L}^\infty(\mathbb{R}_+\times \mathbb{R})} + \sup\nolimits_{t>0} \mathrm{TV}(v(t,\cdot)) < +\infty\Big\}
\end{align*}
and let $u$ be the entropy solution of the scalar conservation law 
\begin{align}\label{eq:cl-f}
    \begin{cases}
        \partial_t u(t,x) + \partial_x f\big(u(t,x)\big) = 0, & (t,x) \in \mathbb{R}_+ \times \mathbb{R}, \\
        u(0,x) = u_0(x), & x \in\mathbb{R}.
    \end{cases}
\end{align}
If $0<\delta_0<T$ and $\delta>0$, then
\begin{align*}
\|v(T-,\cdot)-u(T,\cdot)\|_{\mathrm{L}^1} &\leq \left\|v(0,\cdot)-u_0\right\|_{\mathrm{L}^1}+\operatorname{TV}\left(u_0\right)\big(2 \delta+\delta_0\|f'\|_{\mathrm{L}^{\infty}}\big)  +\nu\left(v, \delta_0\right)-\Lambda_{\delta, \delta_0}(v, u),
\end{align*}
where
\begin{align*}
\nu_t(v, \sigma)&\coloneqq \sup_{s\in[0,\sigma]} \|v(t+s,\cdot)-v(t,\cdot)\|_{\mathrm{L}^1}, \qquad \mathrm{for\ all}\ t>0,\,\sigma>0, \\ 
\nu(v, \sigma)&\coloneqq \sup _{t \in[0, T]} \nu_t(v, \sigma), \qquad \mathrm{for\ all}\ \sigma>0, \\
\Lambda_T(v, \phi, c)&\coloneqq  \int_0^T \int_{\mathbb{R}}\left(|v-c| \partial_t \phi+\psi_c(v) \partial_x \phi\right) \, \mathrm d x \, \mathrm d t -\int_{\mathbb{R}}|v(T,x)-c| \phi(T,x) \, \mathrm  d x \\
& \qquad\qquad +\int_{\mathbb{R}}|v(0,x)-c| \phi(0,x) \, \mathrm d x, \qquad \mathrm{for\ all}\ \phi \in \mathrm{C}_\mathrm{c}^1(\mathbb{R}_+\times\mathbb{R},\mathbb{R}_+) ,\, c\in\mathbb{R}, \\
\Lambda_{\delta, \delta_0}(v, u)&\coloneqq  \int_0^T \int_{\mathbb{R}} \Lambda_T\left(v, \Omega\left(\cdot, t^{\prime}, \cdot, x^{\prime}\right), u\left(t^{\prime},x^{\prime}\right)\right) \, \mathrm d x^{\prime} \, \mathrm d t', 
\end{align*}
with  $\omega \in C_c^{\infty}(\mathbb{R})$ being a standard mollifier, i.\,e., an even function satisfying $\operatorname{supp} \omega \subset[-1,1]$, $0 \leq$ $\omega \leq 1$, $\omega$ increasing on $[-1,0]$, and $\int_{\mathbb{R}} \omega(z) \, \mathrm  d z=1$, and $\omega_{\delta}(z)\coloneqq\frac{1}{\delta} \omega\left(\frac{z}{\delta}\right)$, 
$$
\Omega\left(t, t^{\prime},x, x^{\prime}\right)\coloneqq\omega_{\delta_0}\left(t-t^{\prime}\right) \omega_{\delta}\left(x-x^{\prime}\right), \qquad\left(t, t^{\prime},x, x^{\prime}\right) \in \mathbb{R}^4,
$$
and $\psi_c(\xi)\coloneqq\sgn{\xi-c}(f(\xi)-f(c))$ is Kru\v{z}kov's entropy flux function.

\begin{align*} v \in \mathcal K \coloneqq \Big\{ v: \mathbb{R}_+\times \mathbb{R} \to \mathbb{R} \, : \ & v(t,\cdot) \in \mathrm{L}^1_{\mathrm{loc}}(\mathbb{R}) \textnormal{ and the right and left limits $v(t \pm, \cdot)$ exist in $\mathrm L^1_{\mathrm{loc}}$} \\ 
&\textnormal{for all $t>0$ \quad\ \, and \quad\ \,  } \|v\|_{\mathrm{L}^\infty(\mathbb{R}_+\times \mathbb{R})} + \sup\nolimits_{t>0} \mathrm{TV}(v(t,\cdot)) < +\infty\Big\}
\end{align*}

We first assume $T=N\tau$ for $N\in\mathbb{N}_+$ and apply \cref{lm:kut} to $v=W_{{\varepsilon},h}$ and $u=\rho$, using the flux function $f(\rho)=\rho V(\rho)$ and Kru\v{z}kov's entropy flux function $\psi_c(\xi)=\sgn{\xi-c}(\xi V(\xi) - cV(c))$. We denote $t_n\coloneqq n\tau$ for $n\geq0$ and $x_{j-1/2}\coloneqq(j-\frac12)h$ for $j\in\mathbb{Z}$.

It is straightforward to verify that $W_{{\varepsilon},h}\in\mathcal{K}$. Then \cref{lm:kut} gives
\begin{align*}
\|W_{{\varepsilon},h}(T-,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} &\leq \left\|W_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1}+\operatorname{TV}\left(\rho_0\right)\left(2 \delta+\delta_0\|V\|_{\mathrm{W}^{1,\infty}}\right) \\
&\qquad +\nu\left(W_{{\varepsilon},h}, \delta_0\right)-\Lambda_{\delta, \delta_0}(W_{{\varepsilon},h}, \rho),
\end{align*}
for any $0<\delta_0<T$ and $\delta>0$, where $\nu$ and $\Lambda_{\delta, \delta_0}$ are as defined in the statement of \cref{lm:kut}.

\uline{Step 1.} For the first term $\left\|W_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1}$, we have
\begin{align*}
    \left\|W_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1} \leq \left\|W_{{\varepsilon},h}(0,\cdot)-\rho_{{\varepsilon},h}(0,\cdot)\right\|_{\mathrm{L}^1} + \left\|\rho_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1},
\end{align*}
where
\begin{align*}
    \left\|W_{{\varepsilon},h}(0,\cdot)-\rho_{{\varepsilon},h}(0,\cdot)\right\|_{\mathrm{L}^1} = h\sum_{j\in\mathbb{Z}} |W_j^0-\rho_j^0| \leq h \sum_{k=0}^\infty k\gamma_k^{{\varepsilon},h}\sum_{j\in\mathbb{Z}} |\rho_{j+1}^0-\rho_j^0| \leq c_\gamma{\varepsilon} \, \mathrm{TV}(\rho_0),
\end{align*}
with $c_\gamma$ specified in \cref{ass:gamma-mom}, and
\begin{align*}
    \left\|\rho_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1} = \sum_{j\in\mathbb{Z}} \int_{x_{j-1/2}}^{x_{j+1/2}} |\rho_0(x)-\rho_j^0|{\, \mathrm{d}x} \leq h \, \mathrm{TV}(\rho_0).
\end{align*}
Therefore, we have
\begin{align*}
    \left\|W_{{\varepsilon},h}(0,\cdot)-\rho_0\right\|_{\mathrm{L}^1} \leq (c_\gamma{\varepsilon}+h)\, \mathrm{TV}(\rho_0).
\end{align*}

\uline{Step 2.} For the term $\nu(W_{{\varepsilon},h}, \delta_0)=\sup_{t\in[0,T]}\nu_t(W_{{\varepsilon},h}, \delta_0)$, we first estimate
\[ \nu_t(W_{{\varepsilon},h}, \delta_0)= \sup_{0\leq s\leq\delta_0} \|W_{{\varepsilon},h}(t+s,\cdot)-W_{{\varepsilon},h}(t,\cdot)\|_{\mathrm{L}^1}. \]
For any $t\in[0,T]$ and $s\in[0,\delta_0]$, suppose that $t\in[t_m,t_{m+1}[$ and $t+s\in[t_n,t_{n+1}[$. Owing to the temporal TV-estimate \cref{eq:TVD-t-general} in \cref{lm:TVD-t-general}, we have
\begin{align*}
    \|W_{{\varepsilon},h}(t+s,\cdot)-W_{{\varepsilon},h}(t,\cdot)\|_{\mathrm{L}^1} = \sum_{j\in\mathbb{Z}} |W_j^n-W_j^m| h \leq \lambda (n-m)h \norm{V}_{\mathrm{W}^{1,\infty}} \mathrm{TV}(\rho_0).
\end{align*}
Noting that $(n-m-1)\tau\le s$ and $\tau=\lambda h$, and taking the supremum over $s\in[0,\delta_0]$ and $t\in[0,T]$ in the above inequality, we obtain that
\begin{align*}
    \nu\left(W_{{\varepsilon},h}, \delta_0\right) \leq (\delta_0+\tau) \norm{V}_{\mathrm{W}^{1,\infty}} \mathrm{TV}(\rho_0).
\end{align*}

\uline{Step 3.} For the term $\Lambda_{\delta, \delta_0}(W_{{\varepsilon},h}, \rho)$, we first consider
\begin{align*}
    \Lambda_T(W_{{\varepsilon},h}, \phi, c)= & \int_0^T \int_{\mathbb{R}}\left(|W_{{\varepsilon},h}-c| \partial_t \phi+\psi_c(W_{{\varepsilon},h}) \partial_x \phi\right) \, \mathrm d x \, \mathrm d t \\
& \qquad -\int_{\mathbb{R}}|W_{{\varepsilon},h}(T,x)-c| \phi(T,x) \, \mathrm  d x+\int_{\mathbb{R}}|W_{{\varepsilon},h}(0,x)-c| \phi(0,x) \, \mathrm d x,
\end{align*}
where $\phi\in\mathrm{C}^1_{\mathrm{c}}(\mathbb{R}_+\times\mathbb{R},\mathbb{R}_+)$ and $c\in\mathbb{R}$.
We have
\begin{align*}
    &\int_0^T \int_{\mathbb{R}}\left(|W_{{\varepsilon},h}-c| \partial_t \phi+\psi_c(W_{{\varepsilon},h}) \partial_x \phi\right) \, \mathrm d x \, \mathrm d t \\
    &= \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} |W_j^n-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x)-\phi(t_n,x) {\, \mathrm{d}x} + \psi_c(W_j^n) \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2})-\phi(t,x_{j-1/2}){\, \mathrm{d}t},
\end{align*}
and
\begin{align*}
    \int_{\mathbb{R}}|W_{{\varepsilon},h}(T,x)-c| \phi(T,x) \, \mathrm  d x = \sum_{j\in\mathbb{Z}} |W_j^N-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_N,x) {\, \mathrm{d}x}, \\
    \int_{\mathbb{R}}|W_{{\varepsilon},h}(0,x)-c| \phi(0,x) \, \mathrm  d x = \sum_{j\in\mathbb{Z}} |W_j^0-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_0,x) {\, \mathrm{d}x}.
\end{align*}
Using summation by parts, we obtain
\begin{align*}
    &\sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} |W_j^n-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x)-\phi(t_n,x) {\, \mathrm{d}x}  \\
    &= \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} \left( |W_j^n-c| - |W_j^{n+1}-c| \right) \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x) {\, \mathrm{d}x} \\
    &\qquad + \sum_{j\in\mathbb{Z}} |W_j^0-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_0,x) {\, \mathrm{d}x} - \sum_{j\in\mathbb{Z}} |W_j^N-c| \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_N,x) {\, \mathrm{d}x}.
\end{align*}
and
\begin{align*}
    &\sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \psi_c(W_j^n) \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2})-\phi(t,x_{j-1/2}){\, \mathrm{d}t} \\
    &= \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \left( \psi_c(W_j^n)-\psi_c(W_{j+1}^n) \right) \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2}) {\, \mathrm{d}t}.
\end{align*}
Therefore, we deduce that
\begin{align*}
    \Lambda_T(W_{{\varepsilon},h}, \phi, c) &= \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} \left( |W_j^n-c| - |W_j^{n+1}-c| \right) \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x) {\, \mathrm{d}x} \\
    &\qquad + \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \left( \psi_c(W_j^n)-\psi_c(W_{j+1}^n) \right) \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2}) {\, \mathrm{d}t}.
\end{align*}
Next, we use the discrete entropy inequality \crefrange{eq:discrete-entropy-2}{eq:entropy-flux-2} in \cref{lm:discrete-entropy-2} to obtain
\begin{align*}
    \Lambda_T(W_{{\varepsilon},h}, \phi, c) &\geq \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} \lambda (\Psi_{j+1/2}^n - \Psi_{j-1/2}^n) \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x) {\, \mathrm{d}x} \\
    &\quad + \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \left( \psi_c(W_j^n)-\psi_c(W_{j+1}^n) \right) \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2}) {\, \mathrm{d}t} \\
    &= \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} \left( \Psi_{j-1/2}^n - \psi_c(W_j^n) \right) \int_{t_n}^{t_{n+1}} \phi(t,x_{j-1/2}) - \phi(t,x_{j+1/2}) {\, \mathrm{d}t} \\
    &\quad + \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \left( \Psi_{j+1/2}^n - \Psi_{j-1/2}^n \right) \left( \lambda \int_{x_{j-1/2}}^{x_{j+1/2}} \phi(t_{n+1},x) {\, \mathrm{d}x} - \int_{t_n}^{t_{n+1}} \phi(t,x_{j+1/2}) {\, \mathrm{d}t} \right),
\end{align*}
where we have used summation by parts in the last step, and $\Psi_{j-1/2}^n$ is as defined in \cref{eq:entropy-flux-2}.

Now we take the particular test function $\Omega(t,t',x,x') = \omega_{\delta_0}(t-t')\omega_\delta(x-x')$
and estimate
\begin{align}\label{eq:estm_LamT}
    &\Lambda_T(W_{{\varepsilon},h}, \Omega(\cdot,t',\cdot,x'), c) \\
    &\geq -\sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} \left| \Psi_{j-1/2}^n - \psi_c(W_j^n) \right| I_j^n(t',x') - \sum_{n=0}^{N-1}\sum_{j\in\mathbb{Z}} \left| \Psi_{j+1/2}^n - \Psi_{j-1/2}^n \right| J_j^n(t',x'), \notag
\end{align}
where
\begin{align*}
    I_j^n(t',x') &\coloneqq \left| \omega_\delta(x_{j-1/2}-x') - \omega_\delta(x_{j+1/2}-x') \right| \int_{t_n}^{t_{n+1}} \omega_{\delta_0}(t-t') {\, \mathrm{d}t}, \\
    J_j^n(t',x') &\coloneqq \left| \lambda \omega_{\delta_0}(t_{n+1}-t') \int_{x_{j-1/2}}^{x_{j+1/2}} \omega_\delta(x-x') {\, \mathrm{d}x} - \omega_\delta(x_{j+1/2}-x') \int_{t_n}^{t_{n+1}} \omega_{\delta_0}(t-t') {\, \mathrm{d}t} \right|.
\end{align*}
To proceed, we need to derive estimates on $\left|\Psi_{j-1/2}^n - \psi_c(W_j^n)\right|$ and $\left|\Psi_{j+1/2}^n - \Psi_{j-1/2}^n\right|$.

For $\left|\Psi_{j-1/2}^n - \psi_c(W_j^n)\right|$, we observe that $\psi_c(W_j^n) = |W_j^n-c|V(c) - W_j^n\left|V(W_j^n)-V(c)\right|$,
thus
\begin{align*}
    \left|\Psi_{j-1/2}^n - \psi_c(W_j^n)\right| &\leq |W_j^n-W_{j-1}^n| V(c) + |W_j^n-W_{j-1}^n|\left|V(W_j^n)-V(c)\right| \\
    &\qquad + \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left|V(W_{j+k}^n)-V(W_j^n)\right| \\
    &\leq 2\norm{V}_{\mathrm{L}^{\infty}} |W_j^n-W_{j-1}^n| + \|V'\|_{\mathrm{L}^\infty} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} |W_{j+k}^n-W_j^n| \\
    &\eqqcolon K_j^n.
\end{align*}
For $\left|\Psi_{j+1/2}^n - \Psi_{j-1/2}^n\right|$, we have
\begin{align*}
    \left|\Psi_{j+1/2}^n - \Psi_{j-1/2}^n\right| &\leq |W_j^n-W_{j-1}^n| V(c) + |W_j^n-W_{j-1}^n|\left|V(W_j^n)-V(c)\right| \\
    &\quad + \Bigg| \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k-1}^n \left(\left|V(W_{j+k}^n)-V(c)\right|-\left|V(W_j^n)-V(c)\right|\right)  \\
    &\qquad\qquad - \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \rho_{j+k}^n \left(\left|V(W_{j+k+1}^n)-V(c)\right|-\left|V(W_j^n)-V(c)\right|\right) \Bigg| \\
    &\leq 2\norm{V}_{\mathrm{L}^{\infty}} |W_j^n-W_{j-1}^n| \\
    &\quad + \Bigg| \sum_{k=0}^\infty \left(\gamma_{k+1}^{{\varepsilon},h}-\gamma_k^{{\varepsilon},h}\right) \rho_{j+k}^n \left(\left|V(W_{j+k+1}^n)-V(c)\right|-\left|V(W_j^n)-V(c)\right|\right) \Bigg| \\
    &\leq 2\norm{V}_{\mathrm{L}^{\infty}} |W_j^n-W_{j-1}^n| + \sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \rho_{j+k}^n \left|V(W_{j+k+1}^n)-V(W_j^n)\right| \\
    &\eqqcolon L_j^n.
\end{align*}
Noting that $K_j^n$ and $L_j^n$ are independent of the choice of $c$, we take $c=\rho(t',x')$ in $\Lambda_T$ and integrate $\Lambda_T(W_{{\varepsilon},h}, \Omega(\cdot,t',\cdot,x'),\rho(t',x'))$ with respect to $t',x'$. Then the estimate \cref{eq:estm_LamT} yields
\begin{align*}
    &\int_0^T\int_{\mathbb{R}} \Lambda_T(W_{{\varepsilon},h}, \Omega(\cdot,t',\cdot,x'),\rho(t',x')) {\, \mathrm{d}x}'{\, \mathrm{d}t}' \\
    &\geq -\sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} K_j^n \int_0^T\int_{\mathbb{R}} I_j^n(t',x') {\, \mathrm{d}x}'{\, \mathrm{d}t}' - \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} L_j^n \int_0^T\int_{\mathbb{R}} J_j^n(t',x') {\, \mathrm{d}x}'{\, \mathrm{d}t}',
\end{align*}
where we have
\begin{align*}
    \int_0^T\int_{\mathbb{R}} I_j^n(t',x') {\, \mathrm{d}x}'{\, \mathrm{d}t}' &\leq \tau\int_{\mathbb{R}} \left| \omega_\delta(x_{j-1/2}-x') - \omega_\delta(x_{j+1/2}-x') \right| {\, \mathrm{d}x}' \\
    &\leq \mathrm{TV}(\omega_\delta)h\tau \leq \frac{2h\tau}{\delta},
\end{align*}
and
\begin{align*}
    \int_0^T\int_{\mathbb{R}} J_j^n(t',x') {\, \mathrm{d}x}'{\, \mathrm{d}t}' &\leq \lambda \int_{x_{j-1/2}}^{x_{j+1/2}} \int_{\mathbb{R}} \left| \omega_\delta(x-x') - \omega_\delta(x_{j+1/2}-x') \right| {\, \mathrm{d}x}' {\, \mathrm{d}x} \\
    &\quad + \int_{t_n}^{t_{n+1}} \int_0^T \left| \omega_{\delta_0}(t-t') - \omega_{\delta_0}(t_{n+1}-t') \right| {\, \mathrm{d}t}' {\, \mathrm{d}t} \\
    &\leq \lambda\, \mathrm{TV}(\omega_\delta) \int_{x_{j-1/2}}^{x_{j+1/2}} |x-x_{j+1/2}| {\, \mathrm{d}x} + \mathrm{TV}(\omega_{\delta_0}) \int_{t_n}^{t_{n+1}} |t-t_{n+1}| {\, \mathrm{d}t} \\
    &\leq \frac{h\tau}{\delta} + \frac{\tau^2}{\delta_0},
\end{align*}
implying that
\begin{align*}
    \int_0^T\int_{\mathbb{R}} \Lambda_T(W_{{\varepsilon},h}, \Omega(\cdot,t',\cdot,x'),\rho(t',x')) {\, \mathrm{d}x}'{\, \mathrm{d}t}' \geq -\frac{2h\tau}{\delta} \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} K_j^n - \left( \frac{h\tau}{\delta} + \frac{\tau^2}{\delta_0} \right) \sum_{n=0}^{N-1} \sum_{j\in\mathbb{Z}} L_j^n.
\end{align*}
We then estimate
\begin{align*}
    \sum_{j\in\mathbb{Z}} K_j^n &= 2\norm{V}_{\mathrm{L}^{\infty}} \sum_{j\in\mathbb{Z}} |W_j^n-W_{j-1}^n| + \|V'\|_{\mathrm{L}^\infty} \sum_{k=0}^\infty \gamma_k^{{\varepsilon},h} \sum_{j\in\mathbb{Z}} |W_{j+k}^n-W_j^n| \\
    &= \left( 2\norm{V}_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^\infty} \sum_{k=0}^\infty k\gamma_k^{{\varepsilon},h} \right) \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n| \\
    &\leq \left( 2\norm{V}_{\mathrm{L}^{\infty}} + c_\gamma \|V'\|_{\mathrm{L}^\infty} \frac{{\varepsilon}}h \right) \mathrm{TV}(\rho_0),
\end{align*}
with $c_\gamma$ specified in \cref{ass:gamma-mom}, and
\begin{align*}
    \sum_{j\in\mathbb{Z}} L_j^n &= 2\norm{V}_{\mathrm{L}^{\infty}} \sum_{j\in\mathbb{Z}} |W_j^n-W_{j-1}^n| + \sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \sum_{j\in\mathbb{Z}} \rho_{j+k}^n \left|V(W_{j+k+1}^n) -V(W_j^n)\right|.
\end{align*}
Using \cref{eq:TV-p1} in \cref{lm:use_for_tv}, we derive
\begin{align*}
    &\sum_{k=0}^\infty (\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}) \sum_{j\in\mathbb{Z}} \rho_{j+k}^n \left| V(W_{j+k+1}^n) - V(W_j^n) \right| \\
    &\leq \sum_{j\in\mathbb{Z}} \left( \sum_{k=0}^\infty \left(\gamma_k^{{\varepsilon},h}-\gamma_{k+1}^{{\varepsilon},h}\right) \left(\sum_{l=0}^k \rho_{j+l}^n\right) \right) \left|V(W_{j+1}^n) -V(W_j^n)\right| \\
    &= \sum_{j\in\mathbb{Z}} W_j^n \left|V(W_{j+1}^n) -V(W_j^n)\right| \\
    &\leq \|V'\|_{\mathrm{L}^\infty} \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n|,
\end{align*}
and thus
\begin{align*}
    \sum_{j\in\mathbb{Z}} L_j^n \leq \left( 2\norm{V}_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^\infty} \right) \sum_{j\in\mathbb{Z}} |W_{j+1}^n-W_j^n| \leq \left( 2\norm{V}_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^\infty} \right) \mathrm{TV}(\rho_0) .
\end{align*}
Finally, we deduce the following estimate on $\Lambda_{\delta,\delta_0}$:
\begin{align*}
    \Lambda_{\delta,\delta_0}(W_{{\varepsilon},h},\rho) &= \int_0^T\int_{\mathbb{R}} \Lambda_T(W_{{\varepsilon},h}, \Omega(\cdot,t',\cdot,x'),\rho(t',x')) {\, \mathrm{d}x}'{\, \mathrm{d}t}' \\
    &\geq -\frac{2h\tau}{\delta} N \left( 2\norm{V}_{\mathrm{L}^{\infty}} + c_\gamma \|V'\|_{\mathrm{L}^\infty} \frac{{\varepsilon}}h \right) \mathrm{TV}(\rho_0) \\
    &\qquad - \left( \frac{h\tau}{\delta} + \frac{\tau^2}{\delta_0} \right) N \left( 2\norm{V}_{\mathrm{L}^{\infty}} + \|V'\|_{\mathrm{L}^\infty} \right) \mathrm{TV}(\rho_0) \\
    &= - T \left( \left(\frac{6h}{\delta}+\frac{2\tau}{\delta_0}\right) \norm{V}_{\mathrm{L}^{\infty}} + \left(\frac{2c_\gamma{\varepsilon}}{\delta}+\frac{h}{\delta}+\frac{\tau}{\delta_0}\right)\|V'\|_{\mathrm{L}^\infty}\right) \mathrm{TV}(\rho_0).
\end{align*}

\uline{Step 4.} Putting together the above estimates, we have
\begin{align*}
&\|W_{{\varepsilon},h}(T-,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} \\
&\leq  (c_\gamma{\varepsilon}+h) \mathrm{TV}(\rho_0) + \left(2 \delta+\delta_0\|V\|_{\mathrm{W}^{1,\infty}}\right) \mathrm{TV}(\rho_0) + (\delta_0+\tau) \norm{V}_{\mathrm{W}^{1,\infty}} \mathrm{TV}(\rho_0) \\
&\qquad + T \left( \left(\frac{6h}{\delta}+\frac{2\tau}{\delta_0}\right) \norm{V}_{\mathrm{L}^{\infty}} + \left(\frac{2c_\gamma{\varepsilon}}{\delta}+\frac{h}{\delta}+\frac{\tau}{\delta_0}\right)\|V'\|_{\mathrm{L}^\infty}\right) \mathrm{TV}(\rho_0).
\end{align*}
By taking appropriate $\delta$ and $\delta_0$ to optimize the right-hand side, we conclude that
\begin{align}\label{eq:conv_rate}
    \|W_{{\varepsilon},h}(T-,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} \leq K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, T}+\sqrt{h\,T} \right)\, \mathrm{TV}(\rho_0),
\end{align}
for all ${\varepsilon},h>0$ and $T=N\tau>0$, where the constant $K>0$ only depends on $\lambda$, $\|V\|_{\mathrm{L}^\infty}$, $\|V'\|_{\mathrm{L}^\infty}$, and $c_\gamma$.

For an arbitrary time $T>0$, let $N\in\mathbb{N}_+$ be chosen such that $N\tau\le T<(N+1)\tau$. Then, by the construction of $W_{{\varepsilon},h}$ in \cref{eq:W_piece_recon}, we have $W_{{\varepsilon},h}(T,\cdot)=W_{{\varepsilon},h}(N\tau,\cdot)$. A triangle inequality yields
\begin{align*}
\|W_{{\varepsilon},h}(T,\cdot)-\rho(T,\cdot)\|_{\mathrm{L}^1} \leq& \|W_{{\varepsilon},h}(N\tau-,\cdot)-\rho(N\tau,\cdot)\|_{\mathrm{L}^1} \\
&\qquad + \|W_{{\varepsilon},h}(N\tau,\cdot)-W_{{\varepsilon},h}(N\tau-,\cdot)\|_{\mathrm{L}^1} + \|\rho(T,\cdot)-\rho(N\tau,\cdot)\|_{\mathrm{L}^1},
\end{align*}
where the first term on the right-hand side is bounded by $K\left( {\varepsilon}+h+\sqrt{{\varepsilon}\, T}+\sqrt{h\,T} \right)\, \mathrm{TV}(\rho_0)$ using \cref{eq:conv_rate}, the second term by $\tau\cdot\norm{V}_{\mathrm{W}^{1,\infty}} \mathrm{TV}(\rho_0)$ using the temporal TV-estimate \cref{eq:TVD-t-general} in \cref{lm:TVD-t-general}, and the last term also by $\tau\cdot\norm{V}_{\mathrm{W}^{1,\infty}} \mathrm{TV}(\rho_0)$ using a temporal TV-estimate of $\rho$ (see, e.\,g., \cite[Lemma 7.5]{MR4789921}), leading to the desired conclusion.

