\end{align}

The assumptions used in \cref{th:main-2} are satisfied. In particular, the conditions \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm} on quadrature weights imply \crefrange{ass:pos-mono}{ass:gamma-mom}.

We observe that the only additional claims in \cref{th:main-1} compared to \cref{th:main-2} concern the convergence of $\rho_{\varepsilon,h}$ and the convergence rate estimate in \cref{eq:conv-rho}. These follow directly from the conclusions of \cref{th:main-2} (namely, from \cref{eq:conv-W-exp}), thanks to \cref{lm:limit-same}, which holds due to the relation \cref{eq:exp-form3}. Indeed, for every $\varepsilon,h > 0$ and $t > 0$, we compute
\begin{align*}
\|\rho_{\varepsilon,h}(t,\cdot) - \rho(t,\cdot) \|_{\mathrm{L}^1}
&\le \|W_{\varepsilon,h}(t,\cdot) - \rho(t,\cdot) \|_{\mathrm{L}^1}
+ \| W_{\varepsilon,h}(t,\cdot) - \rho_{\varepsilon,h}(t,\cdot) \|_{\mathrm{L}^1} \\
&\le K\left( \varepsilon + h + \sqrt{\varepsilon\, t} + \sqrt{h\, t} \right) \mathrm{TV}(\rho_0)
+ c\varepsilon\, \mathrm{TV}(\rho_0),
\end{align*}
where we used the triangle inequality, \cref{eq:conv-W-exp}, \cref{lm:limit-same}, and the spatial TV-estimate in \cref{lm:TVD-x}.

\begin{align*}
\|\rho_{\varepsilon,h}(t,\cdot) - \rho(t,\cdot) \|_{\mathrm{L}^1}
&\le \|W_{\varepsilon,h}(t,\cdot) - \rho(t,\cdot) \|_{\mathrm{L}^1}
+ \| W_{\varepsilon,h}(t,\cdot) - \rho_{\varepsilon,h}(t,\cdot) \|_{\mathrm{L}^1} \\
&\le K\left( \varepsilon + h + \sqrt{\varepsilon\, t} + \sqrt{h\, t} \right) \mathrm{TV}(\rho_0)
+ c\varepsilon\, \mathrm{TV}(\rho_0),
\end{align*}

\label{rk:CFL}
    The maximum principle in \cref{lem:maxm_prcp} is a prerequisite for all results in this work, and so is the CFL condition \cref{ass:CFL-max}. The spatial TV-estimate in \cref{lm:TVD-x-2} needs a stronger CFL condition stated in \cref{ass:CFL}, which is thus used in the statement of \cref{th:main-2}. 
    On the other hand, in the specific case of the exponential kernel, the CFL condition \cref{ass:CFL-max} is sufficient for the same spatial TV-estimate in \cref{lm:TVD-x}, and thus \cref{th:main-1} holds.


Alternatively, we can discretize \cref{eq:WWxq} as
\begin{align*}
    \frac{W_{j+1}^n - W_j^n}{h} = \frac1{\varepsilon} (W_j^n - \rho_j^n).
\end{align*}
This discretization is equivalent to using the quadrature weights
\begin{align*}
    \gamma_k^{{\varepsilon},h} \coloneqq \frac{h}{{\varepsilon}} \left( 1-\frac{h}{{\varepsilon}} \right)^k,
\end{align*}
which satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm} when $h<{\varepsilon}$.
The conclusion of \cref{th:main-1} then holds, provided that the spatial mesh size $h$ does not exceed the nonlocal horizon $\varepsilon$. Hence, we achieve conditional asymptotic compatibility.

 \label{lm:entro-disc-2}  
Let us assume that \crefrange{ass:ic}{ass:V} hold, the quadrature weights satisfy \crefrange{eq:geometric-gamma}{eq:geometric-gamma-assm}, and the CFL condition \cref{ass:CFL-max} holds. 
Let $\{\rho_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ and $\{W_j^n\}_{j\in\mathbb{Z}}^{n\geq0}$ be the numerical solutions constructed with the numerical scheme \crefrange{eq:godunov}{eq:ini_cond_discrete}. Then the following discrete entropy inequality holds: 
\begin{align}\label{eq:discrete-entropy}
    \frac{|\rho_j^{n+1}-c|-|\rho_j^n-c|}{\tau} + \frac{\Psi_c(\rho_j^n, W_{j+1}^n) - \Psi_c(\rho_{j-1}^n, W_j^n)}{h} \leq 0,
\end{align}
for all $c \in \mathbb{R}$ and  $\Psi_c(\rho,W)\coloneqq |\rho-c|V(W) - c|V(W)-V(c)|$.

Noting that $0\leq\rho_j^n,W_j^n\leq1$ for all $j,n$ (from \cref{lem:maxm_prcp} and \cref{rk:W}), it suffices to show \cref{eq:discrete-entropy} for $c\in(0,1)$.
From \cref{eq:godunov}, we write
\begin{align*}
\rho_j^{n+1} = \rho_j^n+\lambda \left( (\rho_{j-1}^n-c) V(W_j^n) - (\rho_j^n-c) V(W_{j+1}^n) + c \left(V(W_j^n)-V(W_{j+1}^n)\right) \right),
\end{align*}
which implies
\begin{align*}
|\rho_j^{n+1}-c| &\leq \lambda V(W_j^n) |\rho_{j-1}^n-c|  + \left| \left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  + \lambda c \left(V(W_j^n)-V(W_{j+1}^n)\right) \right|.
\end{align*}
We denote $R\coloneqq (1-\lambda V(W_{j+1}^n)) (\rho_j^n-c)  + \lambda c (V(W_j^n)-V(W_{j+1}^n))$ and discuss the following cases. 

\begin{enumerate}[label={\uline{Case \arabic*.}}]
    \item \label{it:c1} If 
$W_{j+1}^n>W_j^n>c$, we have
\[ \left|V(W_j^n)-V(W_{j+1}^n)\right| = V(W_j^n)-V(W_{j+1}^n) = \left|V(W_{j+1}^n)-V(c)\right| - \left|V(W_j^n)-V(c)\right|, \]
yielding
\begin{align}\label{eq:R_estm}
    |R| \leq \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c| + \lambda c \left(\left|V(W_{j+1}^n)-V(c)\right| - \left|V(W_j^n)-V(c)\right|\right).
\end{align}
\item \label{it:c2} If $W_{j+1}^n<W_j^n \leq c$, we have
\[ \left|V(W_j^n)-V(W_{j+1}^n)\right| = V(W_{j+1}^n) - V(W_j^n) = \left|V(W_{j+1}^n)-V(c)\right| - \left|V(W_j^n)-V(c)\right|, \]
which also yields \cref{eq:R_estm}. 
\item \label{it:c3} If $W_j^n>c$ and $W_{j+1}^n\leq W_j^n$,  the identity \cref{eq:exp-form3} implies $\rho_j^n\geq W_j^n>c$, and consequently
\[ \left|V(W_j^n)-V(c)\right| \leq \left|V(\rho_j^n)-V(c)\right| \leq \|V'\|_{\mathrm{L}^\infty} |\rho_j^n-c|. \]
Let $R_1\coloneqq \left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  + \lambda c \left(V(W_j^n)-V(c)\right)$, using the CFL condition \cref{ass:CFL-max}, we have
\begin{align*}
    \lambda c\left|V(W_j^n)-V(c)\right| \leq \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c|,
\end{align*}
thus $\sgn{R_1}=\sgn{\rho_j^n-c}=1$ and
\begin{align*}
    |R| &\leq R_1  + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  + \lambda c \left(V(W_j^n)-V(c)\right) + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c| - \lambda c \left|V(W_j^n)-V(c)\right| + \lambda c \left|V(W_{j+1}^n)-V(c)\right|; 
\end{align*}
so we still obtain \cref{eq:R_estm}.

\item \label{it:c4} If $W_j^n \leq c$ and $W_{j+1}^n\geq W_j^n$, by similar arguments as in \cref{it:c3}, we obtain $\rho_j^n\leq W_j^n \leq c$ and $\sgn{R_1}=\sgn{\rho_j^n-c}=-1$, giving
\begin{align*}
    |R| &\leq -R_1  + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= -\left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  -\lambda c \left(V(W_j^n)-V(c)\right) + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c| - \lambda c \left|V(W_j^n)-V(c)\right| + \lambda c \left|V(W_{j+1}^n)-V(c)\right|;
\end{align*}
so we still obtain \cref{eq:R_estm}.
\end{enumerate}
In summary, the estimate \cref{eq:R_estm} holds in all cases, and it gives
\begin{align*}
    |\rho_j^{n+1}-c| & \leq |\rho_j^n-c| + \lambda \Big( |\rho_{j-1}^n-c| V(W_j^n) - |\rho_j^n-c|V(W_{j+1}^n) \\ &\qquad\qquad - c \left(\left|V(W_j^n)-V(c)\right| - \left|V(W_{j+1}^n)-V(c)\right|\right) \Big) \\
    &= |\rho_j^n-c| + \lambda \big(\Psi_c(\rho_{j-1}^n, W_j^n) - \Psi_c(\rho_j^n, W_{j+1}^n)\big).
\end{align*}
Therefore, we deduce the discrete entropy inequality \cref{eq:discrete-entropy}.

\begin{align*}
    |R| &\leq R_1  + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  + \lambda c \left(V(W_j^n)-V(c)\right) + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c| - \lambda c \left|V(W_j^n)-V(c)\right| + \lambda c \left|V(W_{j+1}^n)-V(c)\right|; 
\end{align*}

\begin{align*}
    |R| &\leq -R_1  + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= -\left(1-\lambda V(W_{j+1}^n)\right) (\rho_j^n-c)  -\lambda c \left(V(W_j^n)-V(c)\right) + \lambda c \left|V(W_{j+1}^n)-V(c)\right| \\
    &= \left(1-\lambda V(W_{j+1}^n)\right) |\rho_j^n-c| - \lambda c \left|V(W_j^n)-V(c)\right| + \lambda c \left|V(W_{j+1}^n)-V(c)\right|;
\end{align*}

We take functions $Q$ and $R$ that satisfy $Q'(\xi)\coloneqq\xi\, V'(\xi)$ and $R'(\xi)\coloneqq V(\xi)$.
Noting that $W_{\varepsilon},\widetilde{W}_{\varepsilon} \in \mathrm{W}^{1,\infty}(\mathbb{R}_+\times\mathbb{R})$ and using \cref{eq:Wevo}, the direct analogue of \cref{eq:cle} and \cref{eq:W}, we obtain
\begin{align*}
    &\frac{\,\mathrm{d}}{\,\mathrm{d} t} \int_{\mathbb{R}} \left|W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)\right|{\, \mathrm{d}x} \\
    &= \int_{\mathbb{R}} \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} \partial_t \left( W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x) \right) {\, \mathrm{d}x} \\
    &= -\int_{\mathbb{R}} \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} \partial_x \left( R(W_{\varepsilon}(t,x)) - R(\widetilde{W}_{\varepsilon}(t,x)) \right) {\, \mathrm{d}x} \\
    &\qquad -\frac1{\varepsilon} \int_{\mathbb{R}} \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} \int_x^\infty \exp\left(\frac{x-y}{{\varepsilon}}\right) \partial_y \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \,\mathrm{d} y {\, \mathrm{d}x} \\
    &\eqqcolon I_1+I_2.
\end{align*}
For the first term, we have\footnote{~Here, we observe that $\operatorname{sign}(v)' = \delta_{\{v=0\}}v'$ holds (in the sense of distributions) for any smooth function $v$ (cf.~\cite[Lemma 2]{MR542510} and \cite[Remark 7.1]{MR4789921}). To apply this to our setting, we may employ approximations (by regularizing the initial data) for $W_{\varepsilon},\,\widetilde{W}_{\varepsilon}$ as in \cite[Theorem 3.1]{MR4651679} or \cite[Lemma 3.1]{MR4855163}.}
\begin{align*}
    I_1 = \int_{\mathbb{R}} 2\delta_{\left\{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x) = 0\right\}} \left( R(W_{\varepsilon}(t,x)) - R(\widetilde{W}_{\varepsilon}(t,x)) \right) \partial_x\left( W_{\varepsilon}(t,x) - \widetilde{W}_{\varepsilon}(t,x) \right) {\, \mathrm{d}x} = 0.
\end{align*}
For the second term, we use Fubini's theorem and integration by parts (noticing that the boundary terms vanish as $W_{\varepsilon},\,\widetilde{W}_{\varepsilon} \in \mathrm{W}^{1,\infty}(\mathbb{R}_+\times\mathbb{R})$) to deduce  
\begin{align*}
    I_2 &= -\frac1{\varepsilon} \int_{\mathbb{R}} \partial_y \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} {\, \mathrm{d}x} \,\mathrm{d} y \\
    &= \frac1{\varepsilon} \int_{\mathbb{R}} \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \sgn{W_{\varepsilon}(t,y)-\widetilde{W}_{\varepsilon}(t,y)} \,\mathrm{d} y \\
    &\qquad  - \frac1{{\varepsilon}^2} \int_{\mathbb{R}} \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} {\, \mathrm{d}x} \,\mathrm{d} y \\
    &\eqqcolon I_{21} + I_{22}.
\end{align*}
Noting that $Q$ is a decreasing function, we have
\begin{align*}
    I_{21} = - \frac1{\varepsilon} \int_{\mathbb{R}} \left| Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right| \,\mathrm{d} y;
\end{align*}
on the other hand,
\begin{align*}
    |I_{22}| &\leq \frac1{{\varepsilon}^2} \int_{\mathbb{R}} \left| Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right| \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) {\, \mathrm{d}x} \,\mathrm{d} y \\
    &= \frac1{\varepsilon} \int_{\mathbb{R}} \left| Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right| \,\mathrm{d} y.
\end{align*}
Therefore, $I_2=I_{21}+I_{22}\leq0$ and we conclude that
\begin{align*}
    \frac{\,\mathrm{d}}{\,\mathrm{d} t} \int_{\mathbb{R}} \left|W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)\right|{\, \mathrm{d}x} \leq 0.
\end{align*}

\begin{align*}
    I_2 &= -\frac1{\varepsilon} \int_{\mathbb{R}} \partial_y \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} {\, \mathrm{d}x} \,\mathrm{d} y \\
    &= \frac1{\varepsilon} \int_{\mathbb{R}} \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \sgn{W_{\varepsilon}(t,y)-\widetilde{W}_{\varepsilon}(t,y)} \,\mathrm{d} y \\
    &\qquad  - \frac1{{\varepsilon}^2} \int_{\mathbb{R}} \left( Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right) \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) \sgn{W_{\varepsilon}(t,x)-\widetilde{W}_{\varepsilon}(t,x)} {\, \mathrm{d}x} \,\mathrm{d} y \\
    &\eqqcolon I_{21} + I_{22}.
\end{align*}

\begin{align*}
    |I_{22}| &\leq \frac1{{\varepsilon}^2} \int_{\mathbb{R}} \left| Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right| \int_{-\infty}^y \exp\left(\frac{x-y}{{\varepsilon}}\right) {\, \mathrm{d}x} \,\mathrm{d} y \\
    &= \frac1{\varepsilon} \int_{\mathbb{R}} \left| Q(W_{\varepsilon}(t,y)) - Q(\widetilde{W}_{\varepsilon}(t,y)) \right| \,\mathrm{d} y.
\end{align*}

It is established in \cite{MR4300935} that the piecewise constant initial data
\begin{align}\label{eq:tvinc_ini}
    \rho_0^\delta(x) \coloneqq 0.5\,\mathds{1}_{]-\delta,-\delta/2[}(x) + \mathds{1}_{[0,\infty[}(x),
\end{align}
where $\delta\in]0,{\varepsilon}]$, induces total variation increase in the solution $\rho_{\varepsilon}$ of  \cref{eq:cle}.

\begin{align*}
E_{j,n}^\rho \coloneqq \frac{|\rho_j^{n+1} - c| - |\rho_j^n - c|}{\tau} + \frac{ \Psi_c(\rho_j^n, \rho_{j+1}^n) - \Psi_c(\rho_{j-1}^n, \rho_j^n) }{h} \leq 0 \quad \text{for all } j, n,
\end{align*}

\begin{align*}
E_{j,n}^W \coloneqq \frac{|W_j^{n+1} - c| - |W_j^n - c|}{\tau} + \frac{ \Psi_c(W_j^n, W_{j+1}^n) -\Psi_c(W_{j-1}^n, W_j^n) }{h} \leq 0 \quad \text{for all } j, n.
\end{align*}

